<?php
declare(strict_types=1);
namespace CommunityHub;
final class LearningAdmin {
 public static function settings(int $id,array $d):void{$title=App::text($d['title']??null,'Title',180);$status=$d['status']??'';if(!in_array($status,['draft','published','archived'],true))throw new HttpError('Select a course status.');$n=[];foreach(['passing_score'=>[0,100],'estimated_minutes'=>[1,100000],'certificate_valid_days'=>[1,36500],'certification_id'=>[1,PHP_INT_MAX]] as $k=>[$min,$max]){$v=$d[$k]??null;if($v===''||$v===null){$n[$k]=null;continue;}if(!is_numeric($v)||!is_finite((float)$v)||(float)$v<$min||(float)$v>$max||($k!=='passing_score'&&(float)$v!==(float)(int)$v))throw new HttpError('Course settings contain an invalid number.');$n[$k]=$k==='passing_score'?(float)$v:(int)$v;}App::transaction(function()use($id,$d,$title,$status,$n){if(!App::row('SELECT id FROM lms_courses WHERE id=? FOR UPDATE',[$id]))throw new HttpError('Course not found.',404);if($n['certification_id']&&!App::row('SELECT id FROM certifications WHERE id=?',[$n['certification_id']]))throw new HttpError('Certification not found.');if($status==='published'){$lessons=App::rows('SELECT l.* FROM lms_lessons l JOIN lms_modules m ON m.id=l.module_id WHERE m.course_id=?',[$id]);if(!array_filter($lessons,fn($l)=>(int)$l['is_required']))throw new HttpError('Add at least one required lesson before publishing.');foreach($lessons as $l)if($l['lesson_type']==='quiz'){$a=Learning::assessment((int)$l['id'],true);$selected=[];foreach($a['questions'] as $q)foreach($a['answers'] as $answer)if($answer['question_id']==$q['id']&&$answer['is_correct'])$selected[$q['id']]=$answer['id'];Learning::grade($a['questions'],$a['answers'],$selected);}}App::query('UPDATE lms_courses SET title=?,description=?,status=?,passing_score=?,estimated_minutes=?,certification_id=?,certificate_valid_days=? WHERE id=?',[$title,App::text($d['description']??'','Description',50000,true)?:null,$status,$n['passing_score'],$n['estimated_minutes'],$n['certification_id'],$n['certificate_valid_days'],$id]);});}
 public static function handle(array $u,string $method,string $path,array $d):void{Domain::role($u,Domain::STAFF);if($method==='POST'){
  if($path==='/lms/admin/courses'){$title=App::text($d['title']??null,'Title',180);$slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower($d['slug']??$title)),'-');$id=App::insert('INSERT INTO lms_courses(title,slug,description,department_id,created_by) VALUES(?,?,?,?,?)',[$title,$slug?:'course-'.bin2hex(random_bytes(4)),$d['description']?:null,!empty($d['department_id'])?App::id($d['department_id']):null,$u['id']]);App::redirect('/lms/admin/courses/'.$id);}
  if(preg_match('~^/lms/admin/courses/(\d+)/settings$~',$path,$m)){self::settings((int)$m[1],$d);App::redirect('/lms/admin/courses/'.$m[1]);}
  if(preg_match('~^/lms/admin/courses/(\d+)/lessons/(\d+)/questions$~',$path,$m)){Learning::addQuestion((int)$m[1],(int)$m[2],$d);App::redirect('/lms/admin/courses/'.$m[1]);}
  if(preg_match('~^/lms/admin/courses/(\d+)/modules(?:/(\d+)/lessons)?$~',$path,$m)){$course=(int)$m[1];$module=isset($m[2])?(int)$m[2]:null;App::transaction(function()use($course,$module,$d){$c=App::row('SELECT status FROM lms_courses WHERE id=? FOR UPDATE',[$course]);if(!$c||$c['status']!=='draft')throw new HttpError('Set the course to draft before adding materials.');$title=App::text($d['title']??null,'Title',180);if($module){if(!App::row('SELECT id FROM lms_modules WHERE id=? AND course_id=?',[$module,$course]))throw new HttpError('Module not found in this course.');if(!in_array($d['lesson_type']??'',['content','video','resource','quiz'],true))throw new HttpError('Select a lesson type.');$url=App::text($d['resource_url']??'','Resource URL',1000,true);if($url&&(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(parse_url($url,PHP_URL_SCHEME),['http','https'],true)))throw new HttpError('Resources must use an HTTP or HTTPS URL.');$minutes=empty($d['estimated_minutes'])?null:App::id($d['estimated_minutes']);if($minutes>100000)throw new HttpError('Enter valid estimated minutes.');$order=App::row('SELECT COALESCE(MAX(sort_order),-1)+1 n FROM lms_lessons WHERE module_id=?',[$module]);App::query('INSERT INTO lms_lessons(module_id,title,lesson_type,content,resource_url,estimated_minutes,sort_order,is_required) VALUES(?,?,?,?,?,?,?,?)',[$module,$title,$d['lesson_type'],$d['content']?:null,$url?:null,$minutes,$order['n'],(int)!empty($d['is_required'])]);}else{$order=App::row('SELECT COALESCE(MAX(sort_order),-1)+1 n FROM lms_modules WHERE course_id=?',[$course]);App::query('INSERT INTO lms_modules(course_id,title,description,sort_order) VALUES(?,?,?,?)',[$course,$title,$d['description']?:null,$order['n']]);}});App::redirect('/lms/admin/courses/'.$course);}
  throw new HttpError('Course builder action not found.',404);
 }if(preg_match('~^/lms/admin/courses/(\d+)$~',$path,$m)){$id=(int)$m[1];$c=App::row('SELECT * FROM lms_courses WHERE id=?',[$id]);if(!$c)throw new HttpError('Course not found.',404);View::layout('Course builder',function()use($c,$id){View::heading($c['title'],'Set the course to draft before adding or changing learning materials.','COURSE BUILDER');View::form('/lms/admin/courses/'.$id.'/settings',['title'=>['label'=>'Title','required'=>true],'description'=>['label'=>'Description','type'=>'textarea'],'status'=>['label'=>'Publication status','options'=>['draft'=>'Draft','published'=>'Published','archived'=>'Archived']],'passing_score'=>['label'=>'Assessment passing score %','type'=>'number'],'estimated_minutes'=>['label'=>'Estimated minutes','type'=>'number'],'certification_id'=>['label'=>'Completion certification','options'=>[''=>'None']+array_column(App::rows('SELECT id,name FROM certifications ORDER BY name'),'name','id')],'certificate_valid_days'=>['label'=>'Certification validity in days','type'=>'number']],'Save settings',$c);foreach(App::rows('SELECT * FROM lms_modules WHERE course_id=? ORDER BY sort_order,id',[$id]) as $module){?><section class="panel"><h2><?=escape($module['title'])?></h2><?php foreach(App::rows('SELECT * FROM lms_lessons WHERE module_id=? ORDER BY sort_order,id',[$module['id']]) as $l){?><article class="lesson"><h3><?=escape($l['title'])?></h3><small><?=escape($l['lesson_type'])?> · <?=$l['is_required']?'Required':'Optional'?></small><?php View::prose($l['content']);if($l['lesson_type']==='quiz'){$a=Learning::assessment((int)$l['id'],true);foreach($a['questions'] as $q){?><h4><?=escape($q['question_text'])?></h4><ul><?php foreach($a['answers'] as $answer)if($answer['question_id']==$q['id']):?><li><?=escape($answer['answer_text'])?> <?=$answer['is_correct']?'(correct)':''?></li><?php endif?></ul><?php }View::form('/lms/admin/courses/'.$id.'/lessons/'.$l['id'].'/questions',['question_text'=>['label'=>'Question','type'=>'textarea','required'=>true],'question_type'=>['label'=>'Question type','options'=>['single'=>'Single choice','true_false'=>'True / false']],'choices'=>['label'=>'Choices, one per line','type'=>'textarea'],'correct_choice'=>['label'=>'Correct choice number','type'=>'number','required'=>true],'points'=>['label'=>'Points','type'=>'number','default'=>1]],'Add question');}?></article><?php }View::form('/lms/admin/courses/'.$id.'/modules/'.$module['id'].'/lessons',['title'=>['label'=>'Lesson title','required'=>true],'lesson_type'=>['label'=>'Type','options'=>['content'=>'Content','video'=>'Video','resource'=>'Resource','quiz'=>'Assessment']],'content'=>['label'=>'Content','type'=>'textarea'],'resource_url'=>['label'=>'Resource URL','type'=>'url'],'estimated_minutes'=>['label'=>'Estimated minutes','type'=>'number'],'is_required'=>['label'=>'Required lesson','type'=>'checkbox','default'=>true]],'Add lesson');?></section><?php }View::form('/lms/admin/courses/'.$id.'/modules',['title'=>['label'=>'Module title','required'=>true],'description'=>['label'=>'Description','type'=>'textarea']],'Add module');});return;}if($path!=='/lms/admin')throw new HttpError('Page not found.',404);View::layout('Course administration',function(){View::heading('Course administration');View::table(App::rows('SELECT id,title,status,updated_at FROM lms_courses ORDER BY updated_at DESC'),['title'=>'Course','status'=>'Status','updated_at'=>'Updated'],function($c){?><a href="/lms/admin/courses/<?=(int)$c['id']?>">Open builder</a><?php });View::form('/lms/admin/courses',['title'=>['label'=>'Course title','required'=>true],'slug'=>'URL slug','description'=>['label'=>'Description','type'=>'textarea'],'department_id'=>['label'=>'Department','options'=>[''=>'Community-wide']+array_column(App::rows('SELECT id,name FROM departments WHERE is_active=1 ORDER BY name'),'name','id')]],'Create draft course');});}
}
